static const char *alias(const char *f) { for (int i = 0; i < NFN; i++) if (!strcmp(f, FN[i][0])) return FN[i][1]; return f; }
typedef struct { int rng, x1, y1, x2, y2; val v; } arg_t;
static val av(const arg_t *a) { return a->rng ? ev(a->x1, a->y1) : a->v; }
static int acount(const arg_t *a) { return a->rng ? (a->x2 - a->x1 + 1) * (a->y2 - a->y1 + 1) : 1; }
static val acell(const arg_t *a, int k) { if (!a->rng) return a->v; int w = a->x2 - a->x1 + 1; return ev(a->x1 + k % w, a->y1 + k / w); }
/* numeros de los argumentos: en rangos solo cuentan las celdas con numero; un error se propaga */
static double *nums(const arg_t *a, int na, int *n, val *err) { int cap = 64; double *o = malloc(cap * sizeof *o); *n = 0; err->t = 0;
    for (int i = 0; i < na; i++) for (int k = 0; k < acount(&a[i]); k++) { val v = acell(&a[i], k); if (v.t == 3) { *err = v; return o; } if (v.t == 1 || (!a[i].rng && v.t == 2 && isnum(v.s))) { if (*n == cap) { cap *= 2; o = realloc(o, cap * sizeof *o); } o[(*n)++] = num(v); } } return o; }
static int dcmp(const void *x, const void *y) { double a = *(const double *)x, b = *(const double *)y; return a < b ? -1 : a > b; }
static int wild(const char *p, const char *s) { if (!*p) return !*s; if (*p == '*') { for (;;) { if (wild(p + 1, s)) return 1; if (!*s) return 0; s++; } } if (!*s) return 0; if (*p != '?' && tolower(*p) != tolower(*s)) return 0; return wild(p + 1, s + 1); }
