static long serial(int y, int m, int d) { y -= m <= 2; long era = (y >= 0 ? y : y - 399) / 400; long yoe = y - era * 400; long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1; return era * 146097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719468 + 25569; } /* dias desde 30/12/1899, como Excel */
static void ymd(long s, int *y, int *m, int *d) { long z = s - 25569 + 719468, era = (z >= 0 ? z : z - 146096) / 146097; long doe = z - era * 146097, yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; long yy = yoe + era * 400, doy = doe - (365 * yoe + yoe / 4 - yoe / 100), mp = (5 * doy + 2) / 153; *d = doy - (153 * mp + 2) / 5 + 1; *m = mp < 10 ? mp + 3 : mp - 9; *y = yy + (*m <= 2); }
static int dval(val v, long *s) { if (v.t == 1) { *s = (long)v.n; return 1; } if (v.t != 2) return 0; int d = 0, m = 0, y = 0; if (sscanf3(v.s, &d, &m, &y) != 3) return 0; if (y < 100) y += 2000; *s = serial(y, m, d); return 1; }
static val dtext(long s) { int y, m, d; ymd(s, &y, &m, &d); char b[20]; snprintf(b, 20, "%02d/%02d/%04d", d, m, y); return TX(b); }
static void case_s(char *s, int up) { for (unsigned char *p = (unsigned char *)s; *p; p++) { if (*p == 0xC3 && p[1]) { p++; if (up && *p >= 0xA0 && *p <= 0xBE && *p != 0xB7) *p -= 0x20; else if (!up && *p >= 0x80 && *p <= 0x9E && *p != 0x97) *p += 0x20; } else *p = up ? toupper(*p) : tolower(*p); } }
